    access: ['LuAccessibility', C.white],
    phone: ['LuSmartphone', C.white],
    brain: ['LuBrain', C.white],
    cloud: ['LuCloudRain', C.white],
    network: ['LuNetwork', C.white],
    database: ['LuDatabase', C.white],
    shield: ['LuShieldCheck', C.white],
    check: ['LuCheck', C.good],
    x: ['LuX', C.critical],
    flask: ['LuFlaskConical', C.white],
    mountain: ['LuMountain', C.white],
    truck: ['LuTruck', C.white],
    plane: ['LuPlane', C.white],
    train: ['LuTrainFront', C.white],
    ship: ['LuShip', C.white],
    gauge: ['LuGauge', C.white],
    map: ['LuMap', C.white],
    wifi: ['LuWifiOff', C.white],
    users: ['LuUsers', C.white],
    clock: ['LuClock', C.white],
    code: ['LuCode', C.white],
    rocket: ['LuRocket', C.white],
    scale: ['LuScale', C.white],
    layers: ['LuLayers', C.white],
    eye: ['LuEye', C.white],
    bug: ['LuBug', C.white],
